eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   weddingData: () => (/* binding */ weddingData)\n/* harmony export */ });\nconst weddingData = {\n    bride: {\n        name: \"Roshni\",\n        fullName: \"Roshni Ambulkar\",\n        parents: \"Beloved daughter of Mr. Premlal Ambulkar\",\n        intro: \"Warm, graceful, and full of light — Roshni brings joy and calm to every moment she enters.\",\n        image: \"/images/bride.jpg\"\n    },\n    groom: {\n        name: \"Sai\",\n        fullName: \"Sai Rao\",\n        parents: \"Cherished son of Mr. Srinivas Rao\",\n        intro: \"Thoughtful, steadfast, and devoted — Sai is the kind of person who makes everyone around him feel at home.\",\n        image: \"/images/groom.jpg\"\n    },\n    // ISO 8601 with IST offset — used for the live countdown\n    weddingDate: \"2026-08-18T04:02:00+05:30\",\n    displayDate: \"Tuesday, 18 August 2026\",\n    heroInviteLine: \"Together with our families\",\n    welcomeMessage: \"We first met at the same company, working in different teams. What started as a simple connection grew into a beautiful journey of over two years filled with friendship, trust, and love. With the blessings and support of both our families, we are now beginning the most special chapter of our lives together. We warmly invite you to celebrate our wedding with us.\",\n    muhurtham: {\n        date: \"Tuesday, 18 August 2026\",\n        time: \"4:02 AM (18 Aug) – Early hours of 19 August\",\n        nakshatra: \"Swathi Nakshatram\",\n        tithi: \"—\",\n        dressSuggestion: \"Traditional South Indian attire — Silk sarees or Pattu pavadai for ladies; Dhoti or Kurta for gentlemen\",\n        quote: \"विवाहः परमो धर्मः\",\n        quoteTranslation: \"Marriage is the highest dharma\"\n    },\n    venue: {\n        name: \"Sai Madhura Banquet Hall\",\n        address: \"Alwyn Cross Road, Hafeezpet, Miyapur, Hyderabad\",\n        mapUrl: \"https://maps.google.com/?q=Sai+Madhura+Banquet+Hall+Hafeezpet+Miyapur+Hyderabad\"\n    },\n    contact: {\n        name: \"Sai Madhura Banquet Hall\",\n        phone: \"+91 83286 14174\"\n    },\n    footerInvitation: \"Together with our families, we request the honour of your presence and blessings as we begin our new journey.\",\n    events: [\n        {\n            id: \"haldi\",\n            name: \"Haldi Ceremony\",\n            date: \"Sunday, 16 August 2026\",\n            time: \"4:00 PM onwards\",\n            venue: \"Sai Madhura Banquet Hall, Hafeezpet, Miyapur, Hyderabad\",\n            description: \"A joyful ceremony where turmeric paste is lovingly applied to bless the couple with radiance and ward off evil before the wedding.\",\n            icon: \"sun\"\n        },\n        {\n            id: \"muhurtham\",\n            name: \"Muhurtham (Wedding)\",\n            date: \"Tuesday, 18 August 2026\",\n            time: \"4:02 AM – Early hours of 19 August\",\n            venue: \"Sai Madhura Banquet Hall, Hafeezpet, Miyapur, Hyderabad\",\n            description: \"The sacred ceremony of Saptapadi and Mangalsutra under Swathi Nakshatram — the auspicious moment when two souls become one.\",\n            icon: \"heart\"\n        },\n        {\n            id: \"reception\",\n            name: \"Wedding Reception\",\n            date: \"Tuesday, 18 August 2026\",\n            time: \"6:00 PM onwards\",\n            venue: \"Sai Madhura Banquet Hall, Hafeezpet, Miyapur, Hyderabad\",\n            description: \"An elegant evening celebration to welcome Sai and Roshni as a couple, and to shower them with your blessings and love.\",\n            icon: \"star\"\n        }\n    ],\n    story: [\n        {\n            id: \"meet\",\n            title: \"Same Company, Different Teams\",\n            date: \"Two Years Ago\",\n            description: \"We first met at the same company, working in different teams. A simple introduction that neither of us knew would change everything.\",\n            icon: \"sparkles\"\n        },\n        {\n            id: \"connection\",\n            title: \"A Simple Connection\",\n            date: \"Growing Closer\",\n            description: \"What started as a simple connection — a smile in the corridor, a conversation over coffee — began to grow into something neither of us could ignore.\",\n            icon: \"heart\"\n        },\n        {\n            id: \"friendship\",\n            title: \"Friendship, Trust & Love\",\n            date: \"Over Two Years\",\n            description: \"Over two beautiful years, the friendship deepened into trust, and the trust blossomed into love. Every moment together felt natural and right.\",\n            icon: \"star\"\n        },\n        {\n            id: \"family\",\n            title: \"Family Blessings\",\n            date: \"The Decision\",\n            description: \"With the blessings and full support of both our families, we made the decision that felt like the most natural step in the world — to be together, forever.\",\n            icon: \"flower\"\n        },\n        {\n            id: \"wedding\",\n            title: \"A New Chapter\",\n            date: \"18 August 2026\",\n            description: \"Now we are beginning the most special chapter of our lives together. We warmly invite you to witness and celebrate this beautiful beginning with us.\",\n            icon: \"heart\"\n        }\n    ],\n    gallery: [\n        {\n            id: \"g1\",\n            src: \"/images/couple-1.jpg\",\n            alt: \"Roshni and Sai together\",\n            caption: \"Our favourite moment\",\n            gradientFrom: \"#C69A3B\",\n            gradientTo: \"#6D1628\"\n        },\n        {\n            id: \"g2\",\n            src: \"/images/couple-2.jpg\",\n            alt: \"A candid smile\",\n            caption: \"Candid happiness\",\n            gradientFrom: \"#8B1E2D\",\n            gradientTo: \"#3a0915\"\n        },\n        {\n            id: \"g3\",\n            src: \"/images/couple-3.jpg\",\n            alt: \"Together outdoors\",\n            caption: \"Golden hour\",\n            gradientFrom: \"#1F4A3D\",\n            gradientTo: \"#0a1f19\"\n        },\n        {\n            id: \"g4\",\n            src: \"/images/couple-4.jpg\",\n            alt: \"Traditional portrait\",\n            caption: \"Traditional joy\",\n            gradientFrom: \"#7A3C1A\",\n            gradientTo: \"#4A0E1A\"\n        },\n        {\n            id: \"g5\",\n            src: \"/images/couple-5.jpg\",\n            alt: \"Portrait together\",\n            caption: \"Always together\",\n            gradientFrom: \"#C69A3B\",\n            gradientTo: \"#1F4A3D\"\n        },\n        {\n            id: \"g6\",\n            src: \"/images/venue.jpg\",\n            alt: \"Sai Madhura Banquet Hall\",\n            caption: \"Our beautiful venue\",\n            gradientFrom: \"#2C3E50\",\n            gradientTo: \"#1F4A3D\"\n        }\n    ]\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./data/wedding.ts\n");

